// ─── Icons (emoji-based, no deps) ────────────────────────────────────────────
const Icon = ({ e, size }) => (
  <span style={{ fontSize: size || 16, lineHeight: 1 }}>{e}</span>
);

// ─── Toast Component ─────────────────────────────────────────────────────────
function Toast({ toasts, dismiss }) {
  return (
    <div className="toast-container">
      {toasts.map((t) => (
        <div key={t.id} className={`toast ${t.type}`} onClick={() => dismiss(t.id)}>
          <Icon e={t.type === "success" ? "✅" : t.type === "error" ? "❌" : "⚠️"} />
          <div>
            <div style={{ fontWeight: 700, fontSize: 13 }}>{t.title}</div>
            {t.msg && <div style={{ fontSize: 12, color: "#6B7280" }}>{t.msg}</div>}
          </div>
        </div>
      ))}
    </div>
  );
}

function useToast() {
  const [toasts, setToasts] = useState([]);
  const add = (title, type = "success", msg = "") => {
    const id = Date.now();
    setToasts((p) => [...p, { id, title, type, msg }]);
    setTimeout(() => setToasts((p) => p.filter((t) => t.id !== id)), 3500);
  };
  const dismiss = (id) => setToasts((p) => p.filter((t) => t.id !== id));
  return { toasts, add, dismiss };
}

// ─── Auth Page ────────────────────────────────────────────────────────────────
function AuthPage({ onLogin, ashaWorkers = [] }) {
  const [role, setRole]       = useState("admin");
  const [email, setEmail]     = useState("");
  const [password, setPass]   = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError]     = useState("");
  const [showPass, setShowP]  = useState(false);
  const [showCreds, setShowCreds] = useState(false);

  const handleLogin = (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);
    setTimeout(() => {
      const emailTrim = email.trim();
      if (role === "admin") {
        if (emailTrim === ADMIN_CREDS.email && password === ADMIN_CREDS.password) {
          onLogin({ role: "admin", email: emailTrim, name: "Admin" });
        } else {
          setError("Invalid email or password. Please try again.");
        }
      } else if (role === "asha") {
        const worker = ashaWorkers.find(
          (w) => w.email.toLowerCase() === emailTrim.toLowerCase() && w.password === password
        );
        if (worker) {
          onLogin({ role: "asha", email: worker.email, name: worker.name, location: worker.location, ashaId: worker.id });
        } else {
          setError("Invalid email or password. Please try again.");
        }
      } else {
        if (emailTrim === PATIENT_CREDS.email && password === PATIENT_CREDS.password) {
          onLogin({ role: "patient", email: emailTrim, name: "Priya Sharma" });
        } else {
          setError("Invalid email or password. Please try again.");
        }
      }
      setLoading(false);
    }, 900);
  };

  return (
    <div className="login-page">
      {/* ── Left Panel – Illustration ── */}
      <div className="login-left">
        <div className="login-illustration-card">
          <img
            className="login-illustration-img"
            src={WOMEN_ILLUSTRATION}
            alt="ASHA workers visiting a family in their community"
          />
        </div>
        <div className="login-left-tagline">
          <span>Empowering</span> ASHA Workers &amp; Communities
        </div>
      </div>

      {/* ── Right Panel – Form ── */}
      <div className="login-right">
        <div className="login-form-panel">
          {/* Brand */}
          <div className="login-brand">
            <div className="login-brand-title">Asha<span>+</span></div>
          </div>

          <div className="login-subtitle">Login with your email and password</div>

          <form onSubmit={handleLogin} style={{ width: "100%" }}>
            {/* Role dropdown */}
            <div className="login-field">
              <select
                className="login-select"
                value={role}
                onChange={(e) => { setRole(e.target.value); setError(""); }}
              >
                <option value="admin">Login as Admin</option>
                <option value="asha">Login as ASHA Worker</option>
                <option value="patient">Login as Patient</option>
              </select>
              <span className="login-select-arrow">▾</span>
            </div>

            {/* Email */}
            <div className="login-field">
              <input
                className="login-input"
                type="email"
                placeholder="Email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            {/* Password */}
            <div className="login-field" style={{ position: "relative" }}>
              <input
                className="login-input"
                type={showPass ? "text" : "password"}
                placeholder="Password"
                value={password}
                onChange={(e) => setPass(e.target.value)}
                required
              />
              <button
                type="button"
                onClick={() => setShowP((p) => !p)}
                style={{
                  position: "absolute", right: 16, top: "50%",
                  transform: "translateY(-50%)",
                  background: "none", border: "none",
                  cursor: "pointer", fontSize: 16, color: "rgba(109,40,217,0.5)",
                }}
              >
                {showPass ? "🙈" : "👁️"}
              </button>
            </div>

            {/* Forgot password */}
            <div style={{ textAlign: "right", marginBottom: 20 }}>
              <span
                className="login-link"
                onClick={() => setShowCreds((p) => !p)}
              >
                {showCreds ? "Hide Demo Credentials" : "Forgot Password?"}
              </span>
            </div>

            {/* Demo creds */}
            {showCreds && (
              <div className="login-demo-creds">
                <div style={{ marginBottom: 6 }}>
                  <b>Admin:</b> admin@ashacare.in / admin123
                </div>
                <div style={{ marginBottom: 6 }}>
                  <b>ASHA Worker (Noida):</b> asha.noida@ashacare.in / asha123
                </div>
                <div>
                  <b>Patient:</b> priya@email.com / patient123
                </div>
              </div>
            )}

            {/* Error */}
            {error && (
              <div className="login-error">{error}</div>
            )}

            {/* Login button */}
            <button
              type="submit"
              className="login-btn"
              disabled={loading}
            >
              {loading ? <span className="spinner" style={{ borderTopColor: "#fff", borderColor: "rgba(255,255,255,0.3)" }} /> : null}
              {loading ? "Signing in…" : "Login"}
            </button>
          </form>

          {/* Register link */}
          <div className="login-register-row">
            Don't have an account?{" "}
            <span className="login-register-link">Register</span>
          </div>
        </div>
      </div>
    </div>
  );
}

